ext('c9_sci_ch7',[
C("🔍","वर्गीकरण क्यों ज़रूरी है",["जीवों की संख्या बहुत ज़्यादा","अध्ययन आसान","आपसी संबंध समझना","विकास की कड़ी देखना"],"धरती पर दस लाख से ज़्यादा तरह के जीव खोजे जा चुके हैं। अगर हर जीव को अलग-अलग पढ़ें तो ज़िंदगी कम पड़ जाएगी। इसलिए वैज्ञानिकों ने एक जैसे गुणों वाले जीवों को एक समूह में रखा। इसे वर्गीकरण कहते हैं। जैसे बाज़ार में दुकानदार सब्ज़ी, मसाले और दाल अलग-अलग रखता है, वैसे ही जीवों को भी समूहों में बाँटा गया। इससे पढ़ाई आसान होती है और पता चलता है कि कौन जीव किसका रिश्तेदार है।"),
Q("वर्गीकरण का मुख्य उद्देश्य क्या है?","जीवों का अध्ययन आसान बनाना और उनके आपसी संबंध समझना","इसे अपने शब्दों में सोचिए... इतने सारे जीव हैं कि उन्हें एक-एक करके पढ़ना कठिन है। समूह बना देने से पढ़ना आसान हो जाता है। साथ ही यह भी पता चलता है कि कौन-से जीव आपस में नज़दीकी रखते हैं। इसलिए उद्देश्य है अध्ययन आसान बनाना और आपसी संबंध समझना।"),
C("📐","वर्गीकरण के आधार",["कोशिका का प्रकार","शरीर का संगठन","पोषण का तरीक़ा","जनन का ढंग"],"वर्गीकरण कुछ ख़ास आधारों पर होता है। पहला, कोशिका में केंद्रक है या नहीं, यानी प्रोकैरियोटिक या यूकैरियोटिक। दूसरा, जीव एक कोशिका का है या कई कोशिकाओं का। तीसरा, पोषण कैसे लेता है, स्वयं बनाकर या दूसरों से लेकर। चौथा, जनन कैसे करता है। इन्हीं आधारों पर व्हिटेकर ने जीवों को पाँच बड़े जगतों में बाँटा। जो आधार जितना बुनियादी है, उसपर बँटवारा उतना पहले होता है।"),
Q("प्रोकैरियोटिक और यूकैरियोटिक में मुख्य अंतर क्या है?","प्रोकैरियोटिक में सुसंगठित केंद्रक नहीं होता, यूकैरियोटिक में होता है","केंद्रक के आधार पर सोचिए... प्रोकैरियोटिक कोशिका में केंद्रक झिल्ली नहीं होती, आनुवंशिक पदार्थ सीधा कोशिका में पड़ा रहता है, जैसे बैक्टीरिया में। यूकैरियोटिक कोशिका में झिल्ली से घिरा सुसंगठित केंद्रक होता है, जैसे पौधों और जंतुओं में। यह अंतर बहुत महत्वपूर्ण है।"),
C("🦠","मोनेरा जगत की विशेषताएँ",["एककोशिकीय, प्रोकैरियोटिक","कुछ स्वपोषी, कुछ विषमपोषी","जीवाणु और नील-हरित शैवाल","हर जगह पाए जाते हैं"],"मोनेरा जगत में सबसे सरल जीव आते हैं। ये एककोशिकीय होते हैं और इनमें केंद्रक नहीं होता। इनमें जीवाणु, यानी बैक्टीरिया और नील-हरित शैवाल आते हैं। कुछ जीवाणु अपना भोजन ख़ुद बनाते हैं और कुछ दूसरों से लेते हैं। ये मिट्टी, पानी, हवा, यहाँ तक कि हमारे पेट में भी पाए जाते हैं। दही जमाने वाले जीवाणु हमारे लिए उपयोगी हैं, पर टाइफ़ाइड और हैजा फैलाने वाले हानिकारक भी होते हैं।"),
C("🍄","कवक और प्रोटिस्टा",["कवक: मृतजीवी, सड़ा भोजन","खमीर और मशरूम","प्रोटिस्टा: अमीबा, पैरामीशियम","यूग्लीना: दोनों के गुण"],"कवक जगत के जीव मृतजीवी होते हैं, यानी सड़े-गले पदार्थ से भोजन लेते हैं। बरसात में रोटी या अचार पर जो फफूँद उगती है, वह कवक ही है। खमीर और मशरूम भी इसी में आते हैं। प्रोटिस्टा जगत में अमीबा और पैरामीशियम जैसे एककोशिकीय यूकैरियोटिक जीव आते हैं। यूग्लीना ख़ास है, क्योंकि धूप में भोजन बनाता है और अँधेरे में दूसरों से भोजन लेता है। यानी उसमें दोनों के गुण हैं।"),
Q("यूग्लीना किस जगत में आता है और क्यों ख़ास है?","प्रोटिस्टा; यह स्वपोषी और विषमपोषी दोनों तरह से पोषण करता है","याद कीजिए... यूग्लीना एककोशिकीय यूकैरियोटिक जीव है, इसलिए प्रोटिस्टा में आता है। इसमें हरित लवक होता है जो धूप में प्रकाश संश्लेषण करता है, पर अँधेरे में यह भोजन बाहर से भी ले लेता है। यही दोहरे पोषण की ख़ूबी इसे ख़ास बनाती है।"),
C("🌿","पादप जगत के पाँच समूह",["थैलोफाइटा: शैवाल","ब्रायोफाइटा: मॉस","टेरिडोफाइटा: फ़र्न","जिम्नोस्पर्म और एंजियोस्पर्म"],"पौधों को सरल से जटिल क्रम में पाँच समूहों में बाँटा गया है। थैलोफाइटा में जड़, तना, पत्ती नहीं होते, जैसे शैवाल। ब्रायोफाइटा पौधों के उभयचर कहलाते हैं, जैसे मॉस, जो नम जगह में उगते हैं। टेरिडोफाइटा में जड़, तना, पत्ती होते हैं पर फूल-बीज नहीं, जैसे फ़र्न। जिम्नोस्पर्म में नंगे बीज होते हैं, जैसे चीड़। और एंजियोस्पर्म में फूल और फल वाले पौधे आते हैं, जैसे आम, गेहूँ और चना।"),
Q("एकबीजपत्री और द्विबीजपत्री का एक-एक उदाहरण दीजिए।","एकबीजपत्री: गेहूँ, मक्का; द्विबीजपत्री: चना, आम","पहचान के लिए बीज देखिए... जिस बीज में एक ही बीजपत्र हो, वह एकबीजपत्री है, जैसे गेहूँ और मक्का। जिसमें दो बीजपत्र हों, जैसे चना और मटर, वह द्विबीजपत्री है। इनकी पत्ती की नसें भी अलग होती हैं। एकबीजपत्री में समानांतर और द्विबीजपत्री में जालिकावत।"),
C("🪱","अकशेरुकी जंतु: आठ संघ",["पोरिफ़ेरा: स्पंज","सीलेन्ट्रेटा: हाइड्रा","प्लैटीहेल्मिंथीज़: फ़ीताकृमि","एनीलिडा, आर्थ्रोपोडा, मोलस्का, एकाइनोडर्मेटा"],"अकशेरुकी जंतुओं में रीढ़ की हड्डी नहीं होती। पोरिफ़ेरा में स्पंज आते हैं, जिनके शरीर में छोटे-छोटे छिद्र होते हैं। सीलेन्ट्रेटा में हाइड्रा और जेलीफ़िश हैं। चपटे कृमि प्लैटीहेल्मिंथीज़ में, जैसे फ़ीताकृमि। एनीलिडा में केंचुआ आता है, जिसके शरीर में छल्ले होते हैं। आर्थ्रोपोडा सबसे बड़ा संघ है, जिसमें तिलचट्टा, मक्खी और झींगा आते हैं। मोलस्का में घोंघा और सीप हैं, और एकाइनोडर्मेटा में तारामछली।"),
Q("सबसे बड़ा जंतु संघ कौन-सा है?","आर्थ्रोपोडा","याद कीजिए... इसमें कीट, मकड़ी, झींगा और केकड़े जैसे जीव आते हैं। इनके पैर जुड़े हुए होते हैं, इसलिए नाम आर्थ्रोपोडा यानी जुड़े पैर वाले। दुनिया के सबसे ज़्यादा जंतु इसी संघ में हैं।"),
C("🐒","कशेरुकी जंतुओं के पाँच वर्ग",["मत्स्य: गलफड़े","उभयचर: जल और थल","सरीसृप: रेंगने वाले","पक्षी और स्तनधारी"],"कशेरुकी जंतुओं में रीढ़ की हड्डी होती है और इन्हें पाँच वर्गों में बाँटा गया है। मत्स्य वर्ग गलफड़ों से साँस लेता है, जैसे रोहू। उभयचर पानी और ज़मीन दोनों पर रहते हैं, जैसे मेंढक। सरीसृप रेंगते हैं और शल्क होते हैं, जैसे साँप और छिपकली। पक्षियों के पंख होते हैं और अंडे देते हैं। स्तनधारी बच्चों को दूध पिलाते हैं और ज़्यादातर बच्चे को जन्म देते हैं, जैसे गाय और मनुष्य।"),
Q("कौन-से स्तनधारी अंडे देते हैं? उदाहरण बताइए।","बत्तखचोंच (प्लैटिपस) और एकिड्ना","सोचिए... ज़्यादातर स्तनधारी बच्चे को जन्म देते हैं, पर कुछ ख़ास अपवाद हैं। ऑस्ट्रेलिया में रहने वाला प्लैटिपस और एकिड्ना अंडे देते हैं, फिर भी बच्चों को दूध पिलाते हैं। इसलिए वे स्तनधारी माने जाते हैं।"),
C("🧪","वैज्ञानिक नाम लिखने के नियम",["वंश का पहला अक्षर बड़ा","जाति का पहला अक्षर छोटा","छपाई में तिरछे अक्षर","हाथ से लिखें तो रेखांकित"],"द्विनाम पद्धति में हर जीव का नाम दो भागों में होता है, पहला वंश और दूसरा जाति। जैसे मनुष्य का नाम होमो सेपियंस है। नियम यह है कि वंश का पहला अक्षर बड़ा और जाति का पहला अक्षर छोटा लिखा जाता है। छपाई में नाम तिरछा लिखा जाता है और हाथ से लिखते समय दोनों शब्दों के नीचे अलग-अलग रेखा खींची जाती है। यह पद्धति कार्ल लीनियस ने दी थी और इससे पूरी दुनिया में एक ही नाम से जीव पहचाना जाता है।"),
Q("आम का वैज्ञानिक नाम और उसे लिखने का नियम बताइए।","मैंजिफ़ेरा इंडिका; वंश बड़ा अक्षर, जाति छोटा अक्षर, दोनों रेखांकित","आम का वैज्ञानिक नाम मैंजिफ़ेरा इंडिका है... पहला शब्द वंश है और दूसरा जाति। वंश का पहला अक्षर बड़ा है और जाति का छोटा। हाथ से लिखते समय दोनों शब्दों को अलग-अलग रेखांकित करना है। यह नियम परीक्षा में अंक दिलाता है।"),
C("✍️","उत्तर लिखने का सुझाव",["तालिका बनाइए","हर समूह का उदाहरण","चित्र अवश्य बनाएँ","मुख्य शब्द रेखांकित करें"],"इस अध्याय में ढेर सारे नाम हैं, इसलिए तालिका बनाकर पढ़िए। एक कॉलम में समूह, दूसरे में मुख्य विशेषता और तीसरे में उदाहरण लिखिए। जगत, संघ और वर्ग का क्रम याद रखने के लिए छोटी कविता या शब्द-श्रृंखला बनाइए। परीक्षा में उत्तर लिखते समय मुख्य शब्द रेखांकित कीजिए और जहाँ ज़रूरत हो, साफ़ चित्र बनाइए। इससे आपके अंक अच्छे आएँगे।"),
],7)
